                                    {
                                        <span class="text-muted">(@((shipment.EstimatedDelivery.Value - DateTime.Today).Days) days)</span>
                                    }
                                }
                                else
                                {
                                    <span class="text-muted">TBD</span>
                                }
                            </dd>
                        </dl>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Shipment>? shipments;
